/* OSCECore v1.0: dependency-free clinical reasoning trainer. Educational use only. */
'use strict';
const SYSTEMS=['MSK','Cardio','Pulm','Renal','GI','Neuro','Endo/Repro'];
const STORE='oscecore_records_v1', CFG_STORE='oscecore_config_v1';
const DEFAULT_CONFIG={systems:[...SYSTEMS],mode:'rapid',difficulty:'mixed',answer:'free',count:10,timer:true,weakOnly:false};
const ACTIONS=[
 ['intro','Introduce yourself / obtain consent','🤝'],
 ['hpi','Clarify onset, course and symptoms','💬'],
 ['associated','Ask associated symptoms / ROS','🗣'],
 ['risk','Ask exposures / risk factors','🔎'],
 ['redflags','Screen for urgent red flags','⚠'],
 ['pmh','Past medical / surgical history','📋'],
 ['meds','Medications and allergies','💊'],
 ['family','Family and social history','🏠'],
 ['vitals','Request vital signs / general assessment','🩺'],
 ['exam','Perform focused physical examination','🫀'],
 ['focused','Perform special tests / maneuvers','✋'],
 ['investigations','Request targeted investigations','🧪']
];
const CHECKLIST=[['intro','Introduction and consent',5],['hpi','History of presenting illness',12],['associated','Associated symptoms / relevant negatives',7],['risk','Risk factors / exposures',5],['redflags','Safety screening',9],['pmh','Past history',4],['meds','Medication / allergy history',4],['family','Family / social context',4],['vitals','General assessment / vital signs',5],['exam','Relevant focused examination',13],['focused','Specific maneuvers',5],['investigations','Appropriate investigations',8],['differential','Prioritized differential considered',6],['plan','Initial management plan documented',8],['counsel','Patient explanation / safety net documented',5]];
const ALIASES={
 'st-elevation myocardial infarction':['stemi','acute stemi'],
 'non-st-elevation myocardial infarction':['nstemi','non st elevation mi'],
 'acute ischemic stroke':['ischemic stroke','cva','acute cerebral infarction'],
 'transient ischemic attack':['tia'],
 'subarachnoid hemorrhage':['sah'],
 'intracerebral hemorrhage':['ich','hemorrhagic stroke'],
 'acute asthma exacerbation':['asthma attack','asthma exacerbation'],
 'chronic obstructive pulmonary disease':['copd'],
 'acute copd exacerbation':['copd exacerbation','aecopd'],
 'pulmonary embolism':['pe'],
 'acute respiratory distress syndrome':['ards'],
 'heart failure with reduced ejection fraction':['hfr ef','hfref','systolic heart failure'],
 'heart failure with preserved ejection fraction':['hfpef','diastolic heart failure'],
 'atrial fibrillation':['afib','af'],
 'av nodal reentrant tachycardia':['avnrt','paroxysmal supraventricular tachycardia','psvt'],
 'ventricular tachycardia':['vt','v tach'],
 'peripheral arterial disease':['pad','peripheral vascular disease'],
 'deep venous thrombosis':['dvt'],
 'rheumatoid arthritis':['ra'],
 'osteoarthritis':['oa'],
 'calcium pyrophosphate deposition disease':['cppd','pseudogout'],
 'systemic lupus erythematosus':['sle','lupus'],
 'giant cell arteritis':['gca','temporal arteritis'],
 'anterior cruciate ligament tear':['acl tear','acl rupture'],
 'medial collateral ligament sprain':['mcl sprain','mcl tear'],
 'benign paroxysmal positional vertigo':['bppv'],
 'guillain-barre syndrome':['gbs','guillain barre'],
 'myasthenia gravis':['mg'],
 'amyotrophic lateral sclerosis':['als','motor neuron disease'],
 'multiple sclerosis':['ms'],
 'normal pressure hydrocephalus':['nph'],
 'benign prostatic hyperplasia':['bph'],
 'acute tubular necrosis':['atn'],
 'acute interstitial nephritis':['ain'],
 'focal segmental glomerulosclerosis':['fsgs'],
 'chronic kidney disease with uremia':['ckd','uremia'],
 'autosomal dominant polycystic kidney disease':['adpkd','polycystic kidney disease'],
 'hemolytic uremic syndrome':['hus'],
 'thrombotic thrombocytopenic purpura':['ttp'],
 'postrenal acute kidney injury':['postrenal aki','obstructive aki'],
 'prerenal acute kidney injury':['prerenal aki'],
 'gastroesophageal reflux disease':['gerd','acid reflux'],
 'peptic ulcer disease':['pud'],
 'clostridioides difficile colitis':['c diff','c difficile colitis','c difficile'],
 'inflammatory bowel disease':['ibd'],
 'irritable bowel syndrome':['ibs'],
 'primary sclerosing cholangitis':['psc'],
 'primary biliary cholangitis':['pbc'],
 'diabetic ketoacidosis':['dka'],
 'hyperosmolar hyperglycemic state':['hhs','honks'],
 'polycystic ovary syndrome':['pcos'],
 'pelvic inflammatory disease':['pid'],
 'premature ovarian insufficiency':['poi','premature ovarian failure'],
 'congenital adrenal hyperplasia due to 21-hydroxylase deficiency':['cah','21 hydroxylase deficiency']
};
function safeLoad(key,fallback){try{let x=JSON.parse(localStorage.getItem(key));return x??fallback}catch{return fallback}}
let records=safeLoad(STORE,[]);if(!Array.isArray(records))records=[];
let config={...DEFAULT_CONFIG,...safeLoad(CFG_STORE,{})};if(!Array.isArray(config.systems))config.systems=[...SYSTEMS];
let page='home',session=null,play=null,libraryFilter='all',librarySearch='',lastSummary=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=sel=>document.querySelector(sel);
const nrm=s=>String(s||'').toLowerCase().replace(/[‐‑‒–—-]/g,' ').replace(/\b(most likely diagnosis|diagnosis is|likely diagnosis|i think it is|i suspect|the patient has|this is|probably|likely|the|a|an)\b/g,' ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
function editDistance(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let curr=[i];for(let j=1;j<=b.length;j++)curr[j]=Math.min(curr[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=curr}return prev[b.length]}
function isCorrect(response,c){let input=nrm(response);if(!input)return false;let options=[c.dx,...(ALIASES[c.dx.toLowerCase()]||[])];if(c.dx==='Non-ST-elevation myocardial infarction') options.push('non st elevation myocardial infarction');for(let a of options){let value=nrm(a);if(value===input)return true;if(value.length>=10&&input.length>=10&&editDistance(value,input)<=1)return true;}return false}
const byId=new Map(CASES.map(c=>[c.id,c]));
function save(){try{localStorage.setItem(STORE,JSON.stringify(records));localStorage.setItem(CFG_STORE,JSON.stringify(config))}catch{toast('Storage blocked. Export progress before leaving this page.')}}
const shuffle=xs=>{let out=[...xs];for(let i=out.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out};
function patientLabel(c){let x=c.patient.match(/^(\d+)(mo)?([MF])$/);if(!x)return c.patient;let desc=x[2]?`${x[1]}-month-old`:`${x[1]}-year-old`;return desc+' '+(x[3]==='F'?(x[2]?'girl':Number(x[1])<18?'girl':'woman'):(x[2]?'boy':Number(x[1])<18?'boy':'man'))}
function lastAttempt(id){for(let i=records.length-1;i>=0;i--){if(records[i].id===id)return records[i]}return null}
function dueCases(){return CASES.filter(c=>{let a=lastAttempt(c.id);return a&&(!a.correct||a.assisted||a.score<70)})}
function overall(){let unique=new Set(records.map(x=>x.id)).size,success=records.filter(x=>x.correct).length;return{unique,success,accuracy:records.length?Math.round(100*success/records.length):0,attempts:records.length,weak:dueCases().length}}
function navHTML(){let ns=[['home','Dashboard','▦'],['builder','Build a session','⚙'],['performance','Performance','▥'],['library','Case library','▤'],['settings','Settings / data','⚑']];return `<aside class="side"><div class="brand"><span class="brand-icon">✚</span><span>OSCE<em>Core</em></span></div><div><div class="side-label">STUDY STUDIO</div><div class="nav">${ns.map(([id,name,icon])=>`<button type="button" data-act="nav" data-page="${id}" class="${page===id?'active':''}"><span class="nav-icon">${icon}</span>${name}</button>`).join('')}</div></div><div class="side-foot"><b>300 original patient cases</b><br>MSK · Cardio · Pulm · Renal · GI · Neuro · Endo/Repro<br><br>Offline-ready · progress saved locally</div></aside>`}
function mobileNav(){return `<div class="mobile-nav"><div class="brand"><span class="brand-icon">✚</span>OSCE<em>Core</em></div><select id="mobilePage" aria-label="Go to page"><option value="home" ${page==='home'?'selected':''}>Dashboard</option><option value="builder" ${page==='builder'?'selected':''}>Session builder</option><option value="performance" ${page==='performance'?'selected':''}>Performance</option><option value="library" ${page==='library'?'selected':''}>Case library</option><option value="settings" ${page==='settings'?'selected':''}>Settings</option></select></div>`}
function shell(html){return `<div class="shell">${navHTML()}<div>${mobileNav()}<main class="main">${html}<footer class="footer-note">OSCECore v1.0 · Educational simulated encounters, not a substitute for supervised clinical training or locally approved guidelines. Explanations are teaching summaries, not patient-specific treatment orders.</footer></main></div></div>`}
function render(){const content=page==='home'?renderHome():page==='builder'?renderBuilder():page==='quiz'?renderQuiz():page==='performance'?renderPerformance():page==='library'?renderLibrary():page==='settings'?renderSettings():renderSessionEnd();$('#app').innerHTML=shell(content);if(page==='quiz'&&play&&play.feedback){let el=$('#reviewSection');if(el)el.scrollIntoView({behavior:'instant',block:'start'})}}
function systemStats(){return SYSTEMS.map(s=>{let ids=CASES.filter(c=>c.system===s).map(c=>c.id);let a=records.filter(r=>ids.includes(r.id));return {name:s,n:ids.length,attempts:a.length,success:a.filter(x=>x.correct).length,attempted:new Set(a.map(x=>x.id)).size,accuracy:a.length?Math.round(a.filter(x=>x.correct).length*100/a.length):null}})}
function renderHome(){let stats=overall();return `<div class="topbar"><div><div class="eyebrow">CLINICAL REASONING STUDIO</div><h1 class="page-title">Your OSCE training desk</h1><p class="sub">Go from an undifferentiated chief complaint to a defensible diagnosis. The specialty stays hidden until you answer.</p></div><span class="pill good">● 300-case library</span></div>
<div class="grid cols-4" style="margin-bottom:20px"><div class="panel stat"><span class="icon">◈</span><label>Available cases</label><b>${CASES.length}</b><small class="muted">7 course domains</small></div><div class="panel stat"><span class="icon">◉</span><label>Cases attempted</label><b>${stats.unique}</b><small class="muted">Unique presentations</small></div><div class="panel stat"><span class="icon">✓</span><label>Diagnostic accuracy</label><b>${stats.accuracy}%</b><small class="muted">${stats.attempts} total attempts</small></div><div class="panel stat"><span class="icon">↻</span><label>Missed / assisted</label><b>${stats.weak}</b><small class="muted">Cases for targeted review</small></div></div>
<div class="panel hero" style="margin-bottom:20px"><div class="eyebrow">YOUR NEXT PATIENT</div><h2>Unpredictable cases.<br>Real clinical reasoning.</h2><p>Practice without seeing the module or diagnosis. Choose rapid recognition or take the full encounter—from introduction to assessment and plan.</p><div class="row" style="margin-top:18px"><button class="btn dark lg" data-act="quickstart" data-mode="rapid">⚡ Rapid diagnosis</button><button class="btn lg" style="background:#103b4b;color:white;border-color:#7daaad" data-act="quickstart" data-mode="full">🩺 Full encounter</button><button class="btn lg" style="background:transparent;color:white;border-color:#7daaad" data-act="nav" data-page="builder">Customize ↗</button></div></div>
<div class="grid cols-3" style="margin-bottom:20px"><button class="card-action" data-act="quickstart" data-mode="rapid"><span class="symbol">⚡</span><strong>Rapid diagnosis</strong><small>Short presentations; optional history, exam and testing; immediate walkthrough after every answer.</small></button><button class="card-action" data-act="quickstart" data-mode="full"><span class="symbol">🩺</span><strong>Full patient encounter</strong><small>Run history, consent, examination, reasoning and plan with an OSCE process checklist.</small></button><button class="card-action" data-act="quickstart" data-mode="mock"><span class="symbol">⏱</span><strong>Mock OSCE circuit</strong><small>Mixed timed full encounters with an end-of-circuit performance summary and immediate case teaching.</small></button></div>
<div class="split"><section class="panel"><h2>Study coverage</h2><p class="small muted" style="margin-top:0">These course labels appear on the dashboard only—not in the patient encounter.</p><div class="row-systems">${systemStats().map(s=>`<div class="sys-row"><strong>${esc(s.name)}</strong><div class="bar"><i style="width:${Math.round(s.attempted/s.n*100)}%"></i></div><span class="muted">${s.attempted}/${s.n}</span></div>`).join('')}</div></section><section class="panel"><h2>Training priorities</h2><p class="muted">Work on cases you haven't seen, or revisit diagnoses you missed or answered with hints.</p><div class="row" style="margin:17px 0"><span class="pill">New: ${CASES.length-stats.unique}</span><span class="pill warn">To review: ${stats.weak}</span></div><div class="grid" style="gap:9px"><button class="btn primary" data-act="nav" data-page="builder">Build a mixed session</button><button class="btn" data-act="weak" ${stats.weak===0?'disabled':''}>↻ Retry missed or assisted</button><button class="btn" data-act="nav" data-page="performance">View performance trends</button></div></section></div>`}
function renderBuilder(){let opts=[['rapid','Rapid diagnosis','Chief complaint → answer → immediate teaching'],['full','Full encounter','Interview → examine → assess → manage'],['mock','Mock OSCE circuit','Timed full encounters with circuit summary']];return `<div class="topbar"><div><div class="eyebrow">SESSION BUILDER</div><h1 class="page-title">Build your practice</h1><p class="sub">Select cases here; the actual patient view will conceal all specialty/course labels and diagnostic categories.</p></div></div><div class="split"><section class="panel"><h2>Training format</h2><div class="grid" style="gap:8px">${opts.map(([id,t,d])=>`<label class="chip ${config.mode===id?'selected':''}" style="border-radius:11px;display:block;cursor:pointer"><input type="radio" name="mode" value="${id}" ${config.mode===id?'checked':''} style="margin-right:9px;accent-color:#0c827b"><b>${t}</b><small class="muted" style="display:block;margin-left:25px">${d}</small></label>`).join('')}</div><hr class="divider"><h3>Include systems</h3><p class="small muted">Every selected system is pooled and shuffled; the course is never displayed during a case.</p><div class="checks">${SYSTEMS.map(s=>`<button class="chip ${config.systems.includes(s)?'selected':''}" data-act="system" data-system="${esc(s)}">${config.systems.includes(s)?'✓ ':''}${esc(s)} <small>(${CASES.filter(c=>c.system===s).length})</small></button>`).join('')}</div><div class="row" style="margin-top:11px"><button class="btn sm" data-act="all-systems">Select all</button><button class="btn sm" data-act="no-systems">Clear</button></div></section><section class="panel"><h2>Session controls</h2><div class="grid cols-2"><div class="field"><label>Difficulty</label><select id="cfgDifficulty"><option value="mixed" ${config.difficulty==='mixed'?'selected':''}>Mixed — best for OSCEs</option><option value="1" ${config.difficulty==='1'?'selected':''}>Core presentations</option><option value="2" ${config.difficulty==='2'?'selected':''}>Intermediate</option><option value="3" ${config.difficulty==='3'?'selected':''}>Advanced / atypical</option></select></div><div class="field"><label>Number of patients</label><select id="cfgCount">${[5,10,20,30,40,60,100,300].map(n=>`<option ${config.count===n?'selected':''} value="${n}">${n} cases</option>`).join('')}</select></div><div class="field"><label>Answer method</label><select id="cfgAnswer"><option value="free" ${config.answer==='free'?'selected':''}>Free response (MC backup)</option><option value="mc" ${config.answer==='mc'?'selected':''}>Multiple choice</option></select></div><div class="field"><label>Timer</label><select id="cfgTimer"><option value="true" ${config.timer?'selected':''}>Show elapsed time</option><option value="false" ${!config.timer?'selected':''}>Hide timer</option></select></div></div><hr class="divider"><label class="checkrow"><input id="cfgWeak" type="checkbox" ${config.weakOnly?'checked':''}>Focus on previously missed or assisted cases</label><p class="notice" style="margin:17px 0">Feedback appears <b>immediately when you answer</b>, in every mode. Rapid cases include optional detailed teaching. Mock OSCE stations keep time pressure but still show post-answer feedback.</p><button class="btn primary lg full" data-act="start" ${config.systems.length===0?'disabled':''}>Start my session →</button><p class="small muted" style="margin-bottom:0">${config.systems.reduce((n,s)=>n+CASES.filter(c=>c.system===s).length,0)} eligible cases before difficulty and review filters.</p></section></div>`}
function preparePlay(){let c=byId.get(session.ids[session.idx]);play={started:Date.now(),hints:[],actions:[],transcript:[{speaker:'patient',text:c.opening}],mcActive:session.answer==='mc',choices:[],feedback:null,answer:'',differential:'',plan:'',counsel:'',reveal:{},correct:false,assisted:false};play.choices=makeChoices(c)}
function startSession(modeOverride=null,specialIds=null){if(config.systems.length===0)return toast('Choose at least one system.');let mode=modeOverride||config.mode;let eligible=CASES.filter(c=>config.systems.includes(c.system)&&(config.difficulty==='mixed'||c.difficulty===Number(config.difficulty)));if(config.weakOnly&&!specialIds){let ids=new Set(dueCases().map(c=>c.id));eligible=eligible.filter(c=>ids.has(c.id))}if(specialIds)eligible=specialIds.map(id=>byId.get(id)).filter(Boolean);if(!eligible.length)return toast('No cases match these filters. Try a broader selection.');let n=specialIds?eligible.length:Math.min(config.count,eligible.length);session={ids:shuffle(eligible).slice(0,n).map(c=>c.id),idx:0,mode,answer:config.answer,timer:config.timer,correct:0,scoreTotal:0,start:Date.now(),results:[]};preparePlay();page='quiz';render();window.scrollTo(0,0)}
function makeChoices(c){let list=[c.dx];let ds=c.differential.split(';').map(x=>x.trim()).filter(Boolean);for(let x of ds){if(!list.some(v=>nrm(v)===nrm(x)))list.push(x)}let sameChief=CASES.filter(other=>other.id!==c.id&&(other.chief.toLowerCase().split(' ').some(word=>word.length>3&&c.chief.toLowerCase().includes(word))||other.system===c.system));let nearby=shuffle(sameChief).sort((a,b)=>Number(b.system===c.system)-Number(a.system===c.system));for(let a of nearby){if(list.length>=4)break;if(!list.some(v=>nrm(v)===nrm(a.dx)))list.push(a.dx)}for(let a of shuffle(CASES)){if(list.length>=4)break;if(!list.includes(a.dx))list.push(a.dx)}return shuffle(list.slice(0,4))}
function getCase(){return byId.get(session.ids[session.idx])}
function fmtTime(ms){let n=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function renderQuiz(){let c=getCase(),full=session.mode!=='rapid',count=session.ids.length,progress=Math.round((session.idx+1)/count*100),answered=!!play.feedback;return `<div class="quiz-top"><div class="row"><span class="pill">PATIENT ${session.idx+1} / ${count}</span><span class="pill">${full?'Clinical encounter':'Rapid diagnosis'}</span>${session.timer?`<span class="pill">⏱ <span id="clock">${fmtTime(Date.now()-play.started)}</span></span>`:''}</div><button class="btn sm danger" data-act="exit">End session</button></div><div class="progress"><i style="width:${progress}%"></i></div><div class="quizgrid"><section class="patient-card"><div class="patient-top"><span class="trackline">PATIENT CHART</span><span class="badge">Undifferentiated presentation</span></div><div class="patient-body"><div class="trackline">Chief complaint</div><h1 class="chief">${esc(c.chief)}</h1><div class="row" style="margin-bottom:16px"><span class="pill">${esc(patientLabel(c))}</span></div><p class="patient-quote">“${esc(c.opening)}”</p>${!answered&&!full?renderRapidReveal(c):''}${full&&!answered?`<div class="notice" style="margin-top:18px">You lead the encounter. Ask targeted questions, request relevant examination findings and investigations, then submit your leading diagnosis.</div>`:''}</div></section><section class="answer-panel">${answered?renderResult(c):full?renderFull(c):renderRapidAnswer(c)}</section></div>${answered?renderReview(c):''}`}
function renderRapidReveal(c){let items=[['history','Request additional history',c.history],['exam','Request examination findings',c.exam],['test','Request relevant investigation results',c.test]];return `<hr class="divider"><div class="sublabel">Information available on request</div><div class="reveal-buttons" style="margin-top:11px">${items.map(([k,label,txt])=>`<div><button class="reveal-button" data-act="reveal" data-type="${k}" ${play.reveal[k]?'disabled':''}>${label}<span>${play.reveal[k]?'✓':'+'}</span></button>${play.reveal[k]?`<div class="info-reveal">${esc(txt)}</div>`:''}</div>`).join('')}</div><p class="small muted">Request as much as you need. Your score records assistance; it does not hide essential findings.</p>`}
function renderRapidAnswer(c){return `<div class="panel"><div class="sectionhead"><h2>What is the most likely diagnosis?</h2><span class="badge a">Your turn</span></div>${renderAnswerControls()}<p class="small muted" style="margin-bottom:0">After submitting, your result and clinical walkthrough appear immediately.</p></div>`}
function renderAnswerControls(){return play.mcActive?`<div class="mc-grid">${play.choices.map((v,i)=>`<button class="mc-option" data-act="choose" data-choice="${esc(v)}"><span class="mc-letter">${'ABCD'[i]}.</span>${esc(v)}</button>`).join('')}</div>${session.answer==='free'?`<button class="btn sm" data-act="free">← Use free response</button>`:''}`:`<div class="answer-input"><input id="dxAnswer" autocomplete="off" spellcheck="true" placeholder="Type the leading diagnosis..." aria-label="Most likely diagnosis"><button class="btn primary" data-act="submit">Submit</button></div><div class="row" style="margin-top:12px"><button class="btn sm" data-act="mc">Need a hint? Switch to multiple choice</button></div>`}
function responseFor(c,type){let h=c.history.split(';').map(x=>x.trim()).filter(Boolean);switch(type){case'intro':return{speaker:'patient',text:'Thank you for introducing yourself. I am comfortable continuing with this interview.'};case'hpi':return{speaker:'patient',text:h[0]||c.history};case'associated':return{speaker:'patient',text:h.slice(1).join('; ')||c.history};case'risk':return{speaker:'patient',text:'The relevant background/exposures described in this case are: '+c.history};case'redflags':return{speaker:'patient',text:'You have asked about important associated warning symptoms. Any positive symptoms explicitly provided are in the history; further negatives have not been scripted.'};case'pmh':return{speaker:'patient',text:'No additional past medical or surgical history has been specified beyond what is already in this patient scenario.'};case'meds':return{speaker:'patient',text:'A complete medication and allergy list has not been specified for this scenario. You are credited for asking.'};case'family':return{speaker:'patient',text:'No further family or social history is specified unless it appears in the clinical history above.'};case'vitals':return{speaker:'exam',text:'Numeric vital signs are not supplied in this case; use the clinical stability clues described. In a real OSCE, check BP, pulse, RR, temperature and SpO₂ where appropriate.'};case'exam':return{speaker:'exam',text:c.exam};case'focused':return{speaker:'exam',text:'Focused findings available: '+c.exam};case'investigations':return{speaker:'exam',text:'Results / indicated investigations: '+c.test};default:return{speaker:'patient',text:c.opening}}}
function renderFull(c){let actionSet=new Set(play.actions);return `<div class="panel encounter-box"><div class="sectionhead"><h2>Standardized patient encounter</h2><span class="badge a">Practice station</span></div><div class="steps">${[['intro','INTRO'],['hpi','HISTORY'],['exam','EXAM'],['investigations','TESTS']].map(([id,t])=>`<div class="step ${actionSet.has(id)?'completed':''}">${t}</div>`).join('')}</div><div id="transcript" class="transcript" aria-label="Patient dialogue">${play.transcript.map(m=>`<div class="message ${m.speaker}"><small>${m.speaker==='you'?'YOU':m.speaker==='exam'?'EXAMINER':'PATIENT'}</small>${esc(m.text)}</div>`).join('')}</div><div class="promptline"><input id="patientQuestion" aria-label="Ask your question" placeholder="Ask a history question or request an exam..." autocomplete="off"><button class="btn primary" data-act="ask-text">Ask</button></div><div class="small muted">Typed questions use limited keyword recognition; the buttons below reliably reveal prewritten answers. This is not an AI conversational patient.</div><div class="action-list">${ACTIONS.map(([id,label,icon])=>`<button class="btn ${actionSet.has(id)?'done':''}" data-act="ask" data-type="${id}">${icon} ${esc(label)} ${actionSet.has(id)?'✓':''}</button>`).join('')}</div><hr class="divider"><div class="sublabel">Assessment and plan</div><div class="field"><label>Prioritized differential (optional but scored for completion)</label><textarea id="differential" placeholder="Most likely diagnosis, important alternatives, can't-miss conditions...">${esc(play.differential)}</textarea></div><div class="field"><label>Initial investigations and management (optional)</label><textarea id="plan" placeholder="Targeted tests, stabilization, treatment, referral/disposition...">${esc(play.plan)}</textarea></div><div class="field"><label>How would you explain and safety-net this patient? (optional)</label><textarea id="counsel" placeholder="Explain the differential, concerns, follow-up and return precautions...">${esc(play.counsel)}</textarea></div><div class="sectionhead"><h2>Submit your leading diagnosis</h2></div>${renderAnswerControls()}<p class="small muted">Your diagnosis is checked automatically. Encounter items are scored for being addressed, not for the clinical quality of free-text documentation; compare your plan with the model answer after submitting.</p></div>`}
function renderResult(c){let result=play.feedback;return `<section class="panel"><div class="post-result ${result.correct?'':'incorrect'}"><div class="sublabel">${result.correct?'✓ RECOGNIZED':'↗ LEARNING OPPORTUNITY'}</div><h2>${result.correct?'Correct diagnosis':'Not quite'}</h2><div style="margin-top:12px"><strong>Answer: ${esc(c.dx)}</strong></div><div class="small" style="margin-top:8px">You answered: ${esc(result.answer||'(no answer)')}</div></div><div class="grid cols-2" style="margin-top:15px"><div class="stat" style="background:#f6fafb;padding:13px;border-radius:11px;min-height:82px"><label>Diagnostic result</label><b style="font-size:23px">${result.correct?'Correct':'Review'}</b></div><div class="stat" style="background:#f6fafb;padding:13px;border-radius:11px;min-height:82px"><label>${session.mode==='rapid'?'Rapid score':'Checklist coverage'}</label><b style="font-size:23px">${result.score}%</b></div></div><p class="small muted">${session.mode==='rapid'?`${play.hints.length} information reveals · ${play.assisted?'multiple-choice assistance used':'unassisted answer format'}`:`Checklist reflects whether you addressed domains, not a validated standardized-patient grade.`}</p><div class="feedback-tools"><button class="btn primary" data-act="next">${session.idx===session.ids.length-1?'Finish session →':'Next patient →'}</button>${session.mode==='rapid'?`<button class="btn" data-act="replay-full">Replay as full encounter</button>`:''}<button class="btn" data-act="toggleall">Expand / collapse walkthrough</button></div></section>`}
const ALT_CASE_MAP={
 'migraine':'Migraine with aura','stroke':'Acute ischemic stroke','ischemic stroke':'Acute ischemic stroke','intracranial hemorrhage':'Intracerebral hemorrhage',
 'asthma':'Acute asthma exacerbation','copd':'Chronic obstructive pulmonary disease','copd exacerbation':'Acute COPD exacerbation',
 'pneumonia':'Community-acquired pneumonia','community pneumonia':'Community-acquired pneumonia','bacterial pneumonia':'Community-acquired pneumonia',
 'tuberculosis':'Pulmonary tuberculosis','pneumothorax':'Primary spontaneous pneumothorax','heart failure':'Heart failure with reduced ejection fraction',
 'hfr ef':'Heart failure with reduced ejection fraction','hfr ef':'Heart failure with reduced ejection fraction','hfref':'Heart failure with reduced ejection fraction',
 'hfpef':'Heart failure with preserved ejection fraction','gastroenteritis':'Viral gastroenteritis','appendicitis':'Acute appendicitis',
 'gerd':'Gastroesophageal reflux disease','ibs':'Irritable bowel syndrome','ibd':'Crohn disease','inflammatory bowel disease':'Crohn disease',
 'bppv':'Benign paroxysmal positional vertigo','tension headache':'Tension-type headache','kidney stone':'Ureterolithiasis',
 'kidney stones':'Ureterolithiasis','pyelonephritis':'Acute pyelonephritis','cystitis':'Acute uncomplicated cystitis',
 'prerenal aki':'Prerenal acute kidney injury','acute kidney injury':'Acute tubular necrosis','fsgs':'Focal segmental glomerulosclerosis',
 'pcos':'Polycystic ovary syndrome','hypothyroidism':'Hashimoto hypothyroidism','hyperthyroidism':'Graves hyperthyroidism',
 'graves disease':'Graves hyperthyroidism','diabetes insipidus':'Central diabetes insipidus','hypoglycemia':'Severe hypoglycemia',
 'av nrt':'AV nodal reentrant tachycardia','avnrt':'AV nodal reentrant tachycardia','stemi':'ST-elevation myocardial infarction',
 'nstemi':'Non-ST-elevation myocardial infarction','acl tear':'Anterior cruciate ligament tear','mcl sprain':'Medial collateral ligament sprain',
 'hemorrhoids':'Internal hemorrhoids','pancreatitis':'Acute pancreatitis','gastritis':'NSAID gastritis','cellulitis':'Osteomyelitis'
};
const CONTRAST={
 'cervicitis':'Cervicitis often causes mucopurulent discharge and an inflamed cervix, with STI NAAT helping identify the pathogen; a persistent suspicious cervical lesion still requires biopsy.',
 'cervical polyp':'A cervical polyp is typically a discrete, often smooth and mobile lesion at the os. Suspicious or irregular lesions require pathologic evaluation rather than assuming benignity.',
 'cellulitis':'Cellulitis produces a more superficial spreading area of warmth and erythema, generally without deep joint pain on passive range of motion or bone-specific findings.',
 'costochondritis':'Pain is reproducible by palpation of costochondral junctions; exertional pressure, diaphoresis or abnormal ECG findings shift concern to cardiac disease.',
 'mechanical back pain':'Mechanical pain is activity/position related with short stiffness; nocturnal pain and marked morning stiffness relieved by exercise suggest inflammatory disease.',
 'viral arthritis':'Viral arthritis is often temporally linked to infection, can be self-limited and needs evaluation for rash/exposure; persistent erosive small-joint synovitis suggests chronic inflammatory arthritis.',
 'inflammatory myopathy':'Primary inflammatory myopathy causes objective proximal muscle weakness, commonly elevated CK, rather than pain-limited movement with preserved strength.',
 'ulnar neuropathy':'Ulnar neuropathy localizes to the ring and little fingers with interosseous weakness, unlike median-nerve symptoms in the radial three-and-a-half digits.',
 'c8 radiculopathy':'C8 radiculopathy can include neck-provoked radicular symptoms and root-pattern weakness beyond isolated ulnar sensory distribution.',
 'thumb cmc osteoarthritis':'Pain and bony tenderness are maximal at the thumb base, often reproduced by grind testing, rather than tendon pain at the radial styloid.',
 'scaphoid fracture':'After trauma, anatomic snuffbox tenderness raises concern for occult scaphoid fracture even if initial radiographs are negative.',
 'dupuytren contracture':'Palmar fascia thickening creates a fixed finger-flexion contracture rather than intermittent locking from an A1 pulley tendon nodule.',
 'inflammatory tenosynovitis':'Inflammatory tenosynovitis often causes more diffuse tendon-sheath swelling, potentially with systemic inflammatory disease and marked pain along the tendon.',
 'impingement syndrome':'Painful overhead activity often preserves power; a major tear adds objective weakness and potentially a positive drop-arm test.',
 'glenohumeral osteoarthritis':'Shoulder arthritis may limit active and passive motion, often with radiographic joint-space narrowing and osteophytes.',
 'radial tunnel syndrome':'Deep proximal forearm pain is commonly more distal to the lateral epicondyle and can be provoked by resisted supination.',
 'ucls injury':'Ligament injury is associated with valgus stress/throwing and instability rather than isolated flexor tendon tenderness.',
 'medial meniscal tear':'Meniscal injury is more associated with joint-line pain and mechanical catching/locking after twisting.',
 'osgood schlatter disease':'Osgood-Schlatter affects growing adolescents at the tibial tubercle rather than the inferior patellar pole.',
 'gastrocnemius strain':'A calf-muscle strain causes focal muscular tenderness while the Achilles tendon and plantarflexion mechanism may remain intact.',
 'calcaneal stress fracture':'Bony heel pain can be provoked by calcaneal squeeze and loading rather than classic first-step plantar fascial tenderness.',
 'tarsal tunnel syndrome':'Burning and tingling in the plantar foot with a nerve-distribution pattern suggest tibial-nerve entrapment.',
 'distal fibular fracture':'Point bony tenderness after trauma or inability to bear weight should trigger Ottawa-rule based radiography.',
 'syndesmotic injury':'A high ankle sprain follows external rotation/dorsiflexion and produces pain above the ankle mortise, often with squeeze/external rotation pain.',
 'medial tibial stress syndrome':'Shin splints produce broad posteromedial tibial tenderness over several centimeters, unlike focal stress-fracture pain.',
 'charcot arthropathy':'Neuropathic joint breakdown may cause a warm swollen foot with surprisingly little pain and often major deformity.',
 'piriformis syndrome':'Buttock-related sciatic irritation often lacks clear root-specific reflex or motor deficits; differentiate from structural radiculopathy.',
 'peripheral neuropathy':'A length-dependent stocking-glove distribution and bilateral reflex loss contrasts with a focal dermatomal or spinal cord pattern.',
 'leg length discrepancy':'Pelvic tilt secondary to unequal leg length can simulate spinal curvature without a structural rotational rib hump.',
 'postural asymmetry':'Postural changes lack the fixed rotational deformity and structural Cobb-angle findings of scoliosis.',
 'malignancy':'Unexplained weight loss, night pain and a cancer history shift concern from a routine benign musculoskeletal process.',
 'lumbar muscle strain':'Muscular strain produces local paraspinal pain and preserved neurologic function without focal vertebral bony tenderness.',
 'hip contusion':'A contusion causes soft-tissue pain after impact, usually with preserved ability to bear weight once pain controlled; fracture must first be excluded.',
 'pelvic fracture':'Pelvic ring tenderness and high-energy mechanism raise a different injury pattern; imaging distinguishes it from proximal femoral fracture.',
 'hip osteoarthritis':'Chronic mechanical groin pain with joint-space narrowing differs from early osteonecrosis, where plain x-rays may still be normal.',
 'femoroacetabular impingement':'Pain is often provoked by hip flexion, adduction and internal rotation, with characteristic bony morphology on imaging.',
 'demand ischemia':'Troponin elevation from supply-demand mismatch must be tied to another physiologic stressor rather than assuming acute plaque rupture.',
 'frequent ectopy':'Premature beats cause an irregular or skipped-beat sensation but usually retain identifiable underlying sinus P waves.',
 'sinus tachycardia':'Sinus tachycardia usually has gradual onset/offset and an identifiable trigger, unlike abrupt reentrant episodes.',
 'svt with aberrancy':'A broad QRS from rate-related conduction can mimic ventricular tachycardia, but VT is the default safety assumption until established.',
 'renal failure':'Renal failure can cause volume overload and pulmonary edema, so check renal function and clarify primary cardiac versus renal cause.',
 'pulmonary disease':'Pulmonary processes typically show lung-specific history/exam or imaging changes without the same cardiac filling-pressure evidence.',
 'restrictive cardiomyopathy':'The myocardium is intrinsically stiff, whereas constrictive pericarditis arises from an externally noncompliant pericardium.',
 'cirrhosis':'Ascites and edema with liver stigmata differ from primarily cardiac venous congestion; labs and imaging help distinguish.',
 'chemical pneumonitis':'Chemical lung injury follows an aspiration event immediately and may improve without bacterial infection; fever and infiltrate later may indicate infection.',
 'chronic bronchitis':'Chronic bronchitis requires a prolonged history of productive cough over consecutive years rather than a discrete acute infectious episode.',
 'bacterial dysentery':'Fever, tenesmus and bloody stools suggest an invasive bacterial colitis rather than uncomplicated watery viral gastroenteritis.',
 'pneumonia alone':'Radiographic consolidation with fever and sputum favors focal lung infection rather than airway-limited bronchitis.',
 'gallstone disease':'RUQ pain after meals with biliary imaging changes is more suggestive than diffuse mucosal dyspepsia.',
 'functional dyspepsia':'Chronic upper abdominal symptoms without an explanatory structural lesion may fit functional dyspepsia after appropriate evaluation.',
 'biliary obstruction':'A cholestatic laboratory pattern and dilated ducts suggest extrahepatic obstruction rather than isolated hepatocellular injury.',
 'cholangiocarcinoma':'Progressive obstructive jaundice with a bile duct mass or dominant stricture raises malignant obstruction.',
 'hemorrhoid thrombosis':'A thrombosed external hemorrhoid produces a tender bluish perianal lump without purulent fluctuation or systemic infection.',
 'fetal distress':'A fetal complication is assessed by maternal stabilization and fetal heart monitoring rather than assuming a maternal diagnosis alone.',
 'pseudoseizure':'Psychogenic nonepileptic events need specialist positive diagnostic evidence; do not infer intentional symptoms.',
 'stroke mimic':'Hypoglycemia, seizure and migraine may produce focal deficits; bedside glucose and acute imaging remain essential.',
 'depression':'Depression may produce cognitive or fatigue symptoms, but fluctuating attention, neurologic findings or endocrine abnormalities need investigation.',
 'panic disorder':'Panic can cause palpitations and sweating without biochemical catecholamine elevation or sustained severe hypertension.',
 'pituitary adenoma':'Pituitary lesions may cause headache or visual changes, but the hormonal profile and MRI distinguish functional tumor type.',
 'gestational hypertension':'New hypertension after 20 weeks without proteinuria or qualifying severe end-organ signs is distinguished from preeclampsia.',
 'cervical polyp':'A benign-looking polyp can cause contact bleeding, but suspicious cervical appearance, persistent symptoms or risk factors demand biopsy.'
};
function resolveAlternate(name){let key=nrm(name),mapped=ALT_CASE_MAP[key];if(mapped){let c=CASES.find(x=>x.dx===mapped);if(c)return c}return CASES.find(x=>nrm(x.dx)===key||((ALIASES[x.dx.toLowerCase()]||[]).some(s=>nrm(s)===key)))||null}
function nearMissExplanation(c){let alts=c.differential.split(';').map(s=>s.trim()).filter(Boolean);return alts.slice(0,3).map(name=>{let other=resolveAlternate(name),tip=CONTRAST[nrm(name)];let detail=other?`A contrasting case would present with: ${other.opening} Typical additional clues: ${other.history} Examination: ${other.exam}`:tip||`Consider this when its characteristic time course or defining exam findings emerge. This patient's ${c.chief.toLowerCase()} is nonspecific, so the distinguishing evidence is the history and targeted examination rather than the chief complaint alone.`;return `<li><strong>${esc(name)}</strong> — ${esc(detail)}</li>`}).join('')}

function teaching(c){let opening=`This ${patientLabel(c)} presents with ${c.chief.toLowerCase()}. ${c.opening}`;return {opening,why:`${c.history} On examination: ${c.exam} Together these findings favor ${c.dx}.`,mechanism:c.mechanism,test:c.test,management:c.management,red:c.redflag}}
function renderReview(c){let t=teaching(c),r=play.feedback;let full=session.mode!=='rapid';let checked=new Set(play.actions);let checklist=CHECKLIST.map(([key,name,pts])=>({key,name,pts,done:key==='differential'?!!play.differential.trim():key==='plan'?!!play.plan.trim():key==='counsel'?!!play.counsel.trim():checked.has(key)}));let missed=checklist.filter(x=>!x.done);return `<div id="reviewSection" class="review"><div class="topbar" style="margin-top:25px;margin-bottom:13px"><div><div class="eyebrow">IMMEDIATE CASE WALKTHROUGH</div><h2 style="font-size:25px;letter-spacing:-.5px;margin:4px 0">The clinical reasoning behind the answer</h2></div><span class="badge a">${esc(c.system)} · ${c.difficulty===1?'Core':c.difficulty===2?'Intermediate':'Advanced'}</span></div><section class="panel" style="margin-bottom:12px"><div class="sublabel">Case summary</div><p class="lead">${esc(t.opening)}</p><p class="lead"><strong>Why ${esc(c.dx)}?</strong> ${esc(t.why)}</p></section>
<details open><summary>① Pattern recognition — the clues that matter</summary><div class="review-body"><ul><li><strong>History:</strong> ${esc(c.history)}</li><li><strong>Examination:</strong> ${esc(c.exam)}</li><li><strong>Confirmation / relevant testing:</strong> ${esc(c.test)}</li></ul><p><strong>Retrieval cue:</strong> When faced with ${esc(c.chief.toLowerCase())}, look for the combination of time course, signature findings, and any risk factors—not one isolated clue.</p></div></details>
<details open><summary>② Differential diagnosis — genuine near misses</summary><div class="review-body"><p>The alternatives below are clinically plausible. Compare their typical course and discriminating findings:</p><ul>${nearMissExplanation(c)}</ul><p>In an OSCE, state what would raise or lower your suspicion for each alternative and which dangerous diagnosis must be excluded first.</p></div></details>
<details open><summary>③ Mechanism / pathophysiology</summary><div class="review-body"><p>${esc(c.mechanism)}</p><p><strong>Link mechanism to presentation:</strong> Explain how the underlying pathology generates the observed symptoms and examination findings; this is often the fastest way to make a diagnosis memorable.</p></div></details>
<details open><summary>④ Appropriate workup and interpretation</summary><div class="review-body"><p>${esc(c.test)}</p><p>Choose investigations based on pretest probability, patient stability and how a result would change management. In an unstable patient, prioritize immediate assessment and resuscitation over nonurgent confirmatory testing.</p></div></details>
<details open><summary>⑤ Initial treatment, disposition and safety</summary><div class="review-body"><p><strong>First steps:</strong> ${esc(c.management)}</p><p><strong>Must-not-miss:</strong> ${esc(c.redflag)}</p><p>Communicate urgency, involve the appropriate service, and give clear return precautions for evolving symptoms when outpatient care is safe.</p></div></details>
<details ${full?'open':''}><summary>⑥ OSCE encounter checklist / model presentation</summary><div class="review-body"><p><strong>High-quality encounter:</strong> Introduce yourself, confirm patient identity and consent, clarify onset and course, elicit targeted positives/negatives and risk factors, ask about medications/allergies, check vitals, examine the relevant systems, and give a prioritized differential with a safe plan.</p>${full?`<p><strong>Checklist domains addressed:</strong> ${checklist.filter(x=>x.done).length} / ${checklist.length}. ${missed.length?`Areas to rehearse next time: ${esc(missed.map(x=>x.name).join('; '))}.`:'All listed process domains were addressed.'}</p><p class="small muted">This is a process audit. It cannot grade whether your free-text plan was appropriate.</p>`:''}<p><strong>Example concise presentation:</strong> “This is a ${esc(patientLabel(c))} presenting with ${esc(c.chief.toLowerCase())}. The most important supporting findings are ${esc(c.history)} On examination, ${esc(c.exam)} My leading diagnosis is ${esc(c.dx)}, with ${esc(c.differential.replace(/;/g,' and'))} as key considerations. I would ${esc(c.management.charAt(0).toLowerCase()+c.management.slice(1))}”</p></div></details>
<section class="panel" style="margin-top:14px"><h3>Make the learning stick</h3><p class="muted">Before moving on, summarize aloud: <b>What were the top three clues? Which near miss was most dangerous? What should happen first?</b></p><div class="row"><button class="btn sm" data-act="copy-review">Copy case debrief</button><button class="btn sm" data-act="next">${session.idx===session.ids.length-1?'Finish circuit':'Next patient →'}</button>${!r.correct?`<button class="btn sm" data-act="self-correct">My answer was an acceptable synonym</button>`:''}</div></section></div>`}
function renderPerformance(){let s=overall();let last=records.slice(-20).reverse();return `<div class="eyebrow">PERFORMANCE ANALYTICS</div><h1 class="page-title">What are you learning?</h1><p class="sub">Diagnostics and checklist coverage are tracked separately. Modules are shown here only, outside the active quiz.</p><div class="grid cols-4" style="margin:22px 0"><div class="panel stat"><label>Unique cases practiced</label><b>${s.unique}/${CASES.length}</b></div><div class="panel stat"><label>Answer accuracy</label><b>${s.accuracy}%</b></div><div class="panel stat"><label>Total attempts</label><b>${s.attempts}</b></div><div class="panel stat"><label>Review targets</label><b>${s.weak}</b></div></div><div class="split"><section class="panel"><h2>Diagnostic accuracy by course</h2><table class="table"><thead><tr><th>Course</th><th>Attempted</th><th>Correct</th></tr></thead><tbody>${systemStats().map(x=>`<tr><td>${esc(x.name)}</td><td>${x.attempted}/${x.n}</td><td>${x.accuracy===null?'—':x.accuracy+'%'}</td></tr>`).join('')}</tbody></table></section><section class="panel"><h2>Focused review</h2><p class="muted">Review cases answered incorrectly, with MC assistance or with multiple reveals. A review session draws from your own saved attempts.</p><button class="btn primary" data-act="weak" ${!s.weak?'disabled':''}>↻ Revisit ${s.weak} cases</button><p class="notice" style="margin-top:20px">Local progress data stays in this browser. Export a JSON backup in Settings to move progress to another device; there is no automatic cross-device synchronization.</p></section></div><section class="panel" style="margin-top:18px"><h2>Recent attempts</h2>${last.length?`<table class="table"><thead><tr><th>When</th><th>Case</th><th>Diagnosis</th><th>Result</th></tr></thead><tbody>${last.map(r=>{let c=byId.get(r.id);return `<tr><td>${new Date(r.at).toLocaleDateString()}</td><td>${esc(c?.chief||'Case')}</td><td>${esc(c?.dx||'')}</td><td>${r.correct?'✓ Correct':'Review'}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">Your attempts will appear here after your first session.</div>'}</section>`}
function renderLibrary(){let list=CASES.filter(c=>(libraryFilter==='all'||libraryFilter===c.system)&&(!librarySearch||[c.dx,c.chief,c.opening].join(' ').toLowerCase().includes(librarySearch.toLowerCase())));return `<div class="eyebrow">CASE CATALOG</div><h1 class="page-title">All ${CASES.length} patients</h1><p class="sub">Browse by teaching topic outside a quiz. Diagnoses and course labels are intentionally hidden once a patient station starts.</p><div class="panel" style="margin:19px 0"><div class="row"><div class="field" style="flex:1;min-width:200px"><label>Search cases</label><input id="libSearch" value="${esc(librarySearch)}" placeholder="Chief complaint or diagnosis"></div><div class="field" style="min-width:150px"><label>Course filter</label><select id="libSystem"><option value="all">All courses</option>${SYSTEMS.map(s=>`<option value="${esc(s)}" ${libraryFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div></div></div><div class="panel"><div class="sectionhead"><h2>${list.length} cases</h2><span class="pill">All 7 meet ≥ 40</span></div><div class="library-list">${list.map(c=>{let prior=lastAttempt(c.id);return `<div class="library-item"><div><strong>${esc(c.dx)}</strong><small>${esc(c.system)} · ${esc(c.chief)} · ${c.difficulty===1?'Core':c.difficulty===2?'Intermediate':'Advanced'} ${prior?'· '+(prior.correct?'✓ Practiced':'↻ Review'):'· Unseen'}</small></div><button class="btn sm" data-act="single" data-id="${c.id}">Practice blind ↗</button></div>`}).join('')}</div></div>`}
function renderSettings(){return `<div class="eyebrow">DATA & REFERENCE</div><h1 class="page-title">Your study setup</h1><div class="split" style="margin-top:20px"><section class="panel"><h2>Progress management</h2><p class="muted">Your attempts and session preferences are stored in this browser with localStorage. Nothing is sent to a server.</p><div class="grid"><button class="btn primary" data-act="export">↓ Export progress as JSON</button><label class="btn" style="cursor:pointer">↑ Import progress JSON <input id="importProgress" type="file" accept=".json,application/json" style="display:none"></label><button class="btn danger" data-act="clear-progress">Clear stored attempts</button></div><p class="small muted">Import merges attempts with existing data; export before clearing or changing browsers.</p></section><section class="panel"><h2>About these cases</h2><p>Every case is an original educational vignette with a diagnosis, prewritten history/exam/test details, near-miss differential, mechanism, management teaching and a safety emphasis.</p><p class="muted">The simulated patient is a finite branching training script, not an AI standardized patient. It does not generate unscripted physical findings. Process-based OSCE checklist coverage is <b>not</b> an official grade.</p><hr class="divider"><h3>Further reading</h3><p><a href="https://www.merckmanuals.com/professional/health-topics" target="_blank" rel="noopener">Merck Manual Professional — clinical topics</a></p><p><a href="https://store.aamc.org/downloadable/download/sample/sample_id/63/" target="_blank" rel="noopener">AAMC EPA 1 — history and physical examination</a></p><p><a href="https://www.lumen.luc.edu/lumen/meded/medicine/medclerk/medicine%20clerkship%20osce%20student%20guide%202022.pdf" target="_blank" rel="noopener">Loyola OSCE student guide</a></p></section></div><div class="panel" style="margin-top:18px"><h2>Important clinical limitation</h2><p class="muted">Built for preclerkship study, not diagnosis of real patients. These original teaching summaries are not individually expert-validated, and practice recommendations may change. Use authoritative course references and current local protocols for drug doses, thresholds, and patient-care decisions. Feedback is formative, not a standardized examiner score.</p></div>`}
function renderSessionEnd(){let count=lastSummary?.count||0,n=lastSummary?.correct||0,avg=count?Math.round(lastSummary.scores.reduce((a,b)=>a+b,0)/count):0;return `<div class="eyebrow">SESSION COMPLETE</div><h1 class="page-title">Circuit complete.</h1><p class="sub">You practiced with hidden course labels and received immediate diagnosis-by-diagnosis teaching.</p><div class="grid cols-3" style="margin:20px 0"><div class="panel stat"><label>Patients seen</label><b>${count}</b></div><div class="panel stat"><label>Correct diagnoses</label><b>${n}/${count}</b></div><div class="panel stat"><label>Average ${lastSummary?.mode==='rapid'?'rapid score':'checklist coverage'}</label><b>${avg}%</b></div></div><div class="panel"><h2>Where next?</h2><p class="muted">Accuracy comes from identifying the key distinguishing features and safe next steps—not simply recalling the final diagnosis. Use performance review to target your misses.</p><div class="row"><button class="btn primary" data-act="nav" data-page="builder">Build another session →</button><button class="btn" data-act="nav" data-page="performance">Review my performance</button><button class="btn" data-act="nav" data-page="home">Dashboard</button></div></div>`}
function toast(s){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=s;document.body.appendChild(d);setTimeout(()=>d.remove(),2500)}
function ask(type,custom=null){if(play.feedback)return;let c=getCase(),label=ACTIONS.find(a=>a[0]===type)?.[1]||custom||'Question';if(!play.actions.includes(type))play.actions.push(type);play.transcript.push({speaker:'you',text:custom||label});play.transcript.push(responseFor(c,type));render();let box=$('#transcript');if(box)box.scrollTop=box.scrollHeight}
function inferIntent(s){let t=s.toLowerCase();if(/(exam|palpat|auscultat|inspection|reflex|strength|test the|press on|special test|range of motion|neuro exam)/.test(t))return'exam';if(/(lab|blood test|urine test|imaging|ct scan|mri|x ray|ultrasound|ecg|ekg|troponin|cbc|culture|investigat)/.test(t))return'investigations';if(/(pulse|vital|blood pressure|oxygen saturation|temperature|spo2|fever now)/.test(t))return'vitals';if(/(medication|medicine|drug|allerg|tablet|prescription)/.test(t))return'meds';if(/(family|smok|alcohol|drug use|sex history|occupation|living|social)/.test(t))return'family';if(/(past medical|medical history|surgery|hospitalization|prior condition)/.test(t))return'pmh';if(/(red flag|numbness in groin|bowel or bladder|fainting|blood in stool|worst headache|chest pain with)/.test(t))return'redflags';if(/(trigger|travel|recent event|exposure|contact|risk|what caused|history of)/.test(t))return'risk';if(/(other symptom|associated|review of systems|also have|anything else)/.test(t))return'associated';if(/(hello|introduce|permission|consent|name|comfortable)/.test(t))return'intro';return'hpi'}
function gatherNotes(){if(!play||page!=='quiz')return;for(let k of ['differential','plan','counsel']){let e=$('#'+k);if(e)play[k]=e.value}}
function scoreChecklist(){let done=new Set(play.actions),weight=CHECKLIST.reduce((s,x)=>s+x[2],0);let taken=CHECKLIST.reduce((s,[k,_,points])=>s+((k==='differential'?play.differential.trim():k==='plan'?play.plan.trim():k==='counsel'?play.counsel.trim():done.has(k))?points:0),0);return Math.round(100*taken/weight)}
function submitAnswer(response,fromMC=false){if(play.feedback)return;gatherNotes();let c=getCase();let correct=isCorrect(response,c);let score=session.mode==='rapid'?(correct?Math.max(25,100-play.hints.length*8-(play.assisted||fromMC&&session.answer==='free'?25:0)):0):scoreChecklist();let assisted=play.assisted||(fromMC&&session.answer==='free');play.correct=correct;play.assisted=assisted;play.feedback={correct,score,answer:response};let result={id:c.id,at:new Date().toISOString(),mode:session.mode,correct,score,assisted,hints:play.hints.length,seconds:Math.round((Date.now()-play.started)/1000),response};records.push(result);session.results.push(result);if(correct)session.correct++;session.scoreTotal+=score;save();render();window.scrollTo({top:0,behavior:'instant'})}
function advance(){if(!play?.feedback)return;if(session.idx===session.ids.length-1){lastSummary={count:session.results.length,correct:session.correct,scores:session.results.map(x=>x.score),mode:session.mode};session=null;play=null;page='end';render();window.scrollTo(0,0)}else{session.idx++;preparePlay();render();window.scrollTo(0,0)}}
function setPage(id){if(page==='quiz'&&id!=='quiz'&&play&&!play.feedback&&!confirm('End this unfinished patient encounter?'))return;if(id==='quiz')return;page=id;render();window.scrollTo(0,0)}
function exportProgress(){let blob=new Blob([JSON.stringify({format:'OSCECore progress v1',exportedAt:new Date().toISOString(),records,config},null,2)],{type:'application/json'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='OSCECore-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function copyReview(){let c=getCase(),x=`OSCECore — ${c.dx}\nChief complaint: ${c.chief}\nOpening: ${c.opening}\nKey history: ${c.history}\nExam: ${c.exam}\nWorkup: ${c.test}\nMechanism: ${c.mechanism}\nDifferential: ${c.differential}\nManagement: ${c.management}\nSafety: ${c.redflag}`;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(x).then(()=>toast('Case debrief copied.')).catch(()=>toast('Clipboard access blocked.'));else toast('Clipboard API unavailable in this browser.')}
document.addEventListener('click',e=>{let b=e.target.closest('[data-act]');if(!b)return;let act=b.dataset.act;if(act==='nav'){setPage(b.dataset.page);return}if(act==='quickstart'){config.mode=b.dataset.mode;config.weakOnly=false;save();startSession(b.dataset.mode);return}if(act==='start'){startSession();return}if(act==='system'){let s=b.dataset.system;config.systems=config.systems.includes(s)?config.systems.filter(x=>x!==s):[...config.systems,s];save();render();return}if(act==='all-systems'){config.systems=[...SYSTEMS];save();render();return}if(act==='no-systems'){config.systems=[];save();render();return}if(act==='weak'){config.weakOnly=true;config.systems=[...SYSTEMS];config.difficulty='mixed';save();startSession('rapid');return}if(act==='reveal'){if(!play.feedback&&!play.reveal[b.dataset.type]){play.reveal[b.dataset.type]=true;play.hints.push(b.dataset.type);render()}return}if(act==='mc'){play.mcActive=true;play.assisted=true;gatherNotes();render();return}if(act==='free'){gatherNotes();play.mcActive=false;render();return}if(act==='choose'){submitAnswer(b.dataset.choice,true);return}if(act==='submit'){submitAnswer($('#dxAnswer')?.value||'',false);return}if(act==='ask'){gatherNotes();ask(b.dataset.type);return}if(act==='ask-text'){let q=$('#patientQuestion')?.value.trim();if(q){gatherNotes();ask(inferIntent(q),q)}return}if(act==='next'){advance();return}if(act==='exit'){if(play&&!play.feedback&&!confirm('End this encounter without submitting?'))return;lastSummary={count:session?.results.length||0,correct:session?.correct||0,scores:session?.results.map(x=>x.score)||[],mode:session?.mode||'rapid'};session=null;play=null;page='end';render();return}if(act==='toggleall'){let ds=[...document.querySelectorAll('#reviewSection details')],all=ds.every(d=>d.open);ds.forEach(d=>d.open=!all);return}if(act==='replay-full'){let id=getCase().id;config.answer='free';config.weakOnly=false;save();startSession('full',[id]);return}if(act==='self-correct'){if(play?.feedback&&!play.correct&&confirm('Mark your diagnosis as clinically equivalent? This changes your saved accuracy.')){play.correct=true;play.feedback.correct=true;let r=records[records.length-1];if(r?.id===getCase().id){r.correct=true;r.manuallyCorrected=true;r.score=session.mode==='rapid'?Math.max(25,100-play.hints.length*8-(play.assisted?25:0)):r.score;play.feedback.score=r.score;session.correct++;save();render()}}return}if(act==='copy-review'){copyReview();return}if(act==='single'){config.answer='free';config.weakOnly=false;save();startSession('rapid',[b.dataset.id]);return}if(act==='export'){exportProgress();return}if(act==='clear-progress'){if(confirm('Delete all saved OSCECore attempts in this browser? Export a backup first if needed.')){records=[];save();render();toast('Local attempts cleared.')}return}});
document.addEventListener('change',e=>{let el=e.target;switch(el.id){case'mobilePage':setPage(el.value);return;case'cfgDifficulty':config.difficulty=el.value;break;case'cfgCount':config.count=Number(el.value);break;case'cfgAnswer':config.answer=el.value;break;case'cfgTimer':config.timer=el.value==='true';break;case'cfgWeak':config.weakOnly=el.checked;break;case'libSystem':libraryFilter=el.value;render();return;case'importProgress':{let file=el.files[0];if(!file)return;file.text().then(t=>{let data=JSON.parse(t);if(!Array.isArray(data.records))throw new Error('Not a valid OSCECore backup.');let valid=data.records.filter(r=>r&&byId.has(r.id)&&typeof r.correct==='boolean'&&typeof r.at==='string');let key=r=>`${r.id}|${r.at}|${r.response||''}`;records=[...new Map([...records,...valid].map(r=>[key(r),r])).values()].sort((a,b)=>a.at.localeCompare(b.at));save();render();toast('Imported '+valid.length+' attempt records.');}).catch(err=>toast('Import failed: '+err.message));return}}
 if(el.name==='mode'){config.mode=el.value;save();render();return}save();if(['cfgDifficulty','cfgWeak'].includes(el.id))render()});
document.addEventListener('input',e=>{if(e.target.id==='libSearch'){librarySearch=e.target.value;let pos=e.target.selectionStart;render();let x=$('#libSearch');if(x){x.focus();x.setSelectionRange(pos,pos)}}if(['differential','plan','counsel'].includes(e.target.id)&&play)play[e.target.id]=e.target.value});
document.addEventListener('keydown',e=>{if(page!=='quiz')return;if(e.key==='Enter'&&!e.shiftKey){if(e.target.id==='dxAnswer'){e.preventDefault();submitAnswer(e.target.value,false)}if(e.target.id==='patientQuestion'){e.preventDefault();let q=e.target.value.trim();if(q){gatherNotes();ask(inferIntent(q),q)}}}});
setInterval(()=>{if(page==='quiz'&&play&&session?.timer){let el=$('#clock');if(el)el.textContent=fmtTime(Date.now()-play.started)}},1000);
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
